{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "description": "JSON Schema for VA Form 10182",
  "properties": {
    "data": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "noticeOfDisagreement"
          ]
        },
        "attributes": {
          "type": "object",
          "properties": {
            "veteran": {
              "type": "object",
              "properties": {
                "ssn": {
                  "allOf": [
                    {
                      "$ref": "ssn.json"
                    },
                    {
                      "description": "Veteran's SSN"
                    }
                  ]
                },
                "icn": {
                  "$ref": "icn.json"
                },
                "firstName": {
                  "allOf": [
                    {
                      "description": "Veteran's first name",
                      "minLength": 1,
                      "maxLength": 255
                    },
                    {},
                    {
                      "$ref": "nonBlankString.json"
                    }
                  ]
                },
                "middleInitial": {
                  "allOf": [
                    {
                      "description": "Veteran's middle initial",
                      "minLength": 1,
                      "maxLength": 1
                    },
                    {
                      "$ref": "nonBlankString.json"
                    }
                  ]
                },
                "lastName": {
                  "allOf": [
                    {
                      "description": "Veteran's last name",
                      "minLength": 1,
                      "maxLength": 255
                    },
                    {
                      "$ref": "nonBlankString.json"
                    }
                  ]
                },
                "fileNumber": {
                  "$ref": "fileNumber.json"
                },
                "birthDate": {
                  "description": "Veteran's birth date",
                  "type": "string",
                  "format": "date"
                },
                "homeless": {
                  "type": "boolean"
                },
                "address": {
                  "$ref": "address.json"
                },
                "phone": {
                  "$ref": "phone.json"
                },
                "email": {
                  "type": "string",
                  "format": "email",
                  "minLength": 6,
                  "maxLength": 255
                },
                "timezone": {
                  "description": "Veteran's timezone. Used for adding the current date to the signature according to the veteran's local time. If not specified, the current UTC date will be used for the signature (which may be ahead or behind the local date).",
                  "$ref": "timezone.json"
                }
              },
              "required": [
                "icn",
                "fileNumber",
                "firstName",
                "lastName",
                "birthDate",
                "homeless",
                "phone",
                "email"
              ],
              "if": {
                "properties": {
                  "homeless": {
                    "const": false
                  }
                }
              },
              "then": {
                "required": [
                  "address"
                ]
              }
            },
            "claimant": {
              "type": "object",
              "description": "If the claimant is a non-Veteran, claimant information is required. Without this information, we will be unable to identify the claimant. If you're a healthcare provider or an employee of a healthcare provider requesting review of a VA payment decision, you must identify the healthcare provider as the claimant and complete all relevant information in the claimant object.",
              "properties": {
                "firstName": {
                  "allOf": [
                    {
                      "description": "Non-Veteran claimant's first name",
                      "minLength": 1,
                      "maxLength": 255
                    },
                    {
                      "$ref": "nonBlankString.json"
                    },
                    {}
                  ]
                },
                "middleInitial": {
                  "allOf": [
                    {
                      "description": "Non-Veteran Claimant's middle initial",
                      "minLength": 1,
                      "maxLength": 1
                    },
                    {
                      "$ref": "nonBlankString.json"
                    }
                  ]
                },
                "lastName": {
                  "allOf": [
                    {
                      "description": "Non-Veteran Claimant's last name",
                      "minLength": 1,
                      "maxLength": 255
                    },
                    {
                      "$ref": "nonBlankString.json"
                    }
                  ]
                },
                "birthDate": {
                  "description": "Non-Veteran claimant's birth date",
                  "type": "string",
                  "format": "date"
                },
                "homeless": {
                  "type": "boolean"
                },
                "address": {
                  "$ref": "address.json"
                },
                "phone": {
                  "$ref": "phone.json"
                },
                "email": {
                  "type": "string",
                  "format": "email",
                  "minLength": 6,
                  "maxLength": 255
                },
                "timezone": {
                  "description": "Veteran's timezone. Used for adding the current date to the signature according to the veteran's local time. If not specified, the current UTC date will be used for the signature (which may be ahead or behind the local date).",
                  "$ref": "timezone.json"
                }
              },
              "required": [
                "homeless",
                "phone",
                "email"
              ],
              "if": {
                "properties": {
                  "homeless": {
                    "const": false
                  }
                }
              },
              "then": {
                "required": [
                  "address"
                ]
              }
            },
            "representative": {
              "type": "object",
              "properties": {
                "name": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 120
                }
              }
            },
            "boardReviewOption": {
              "type": "string",
              "enum": [
                "direct_review",
                "evidence_submission",
                "hearing"
              ]
            },
            "hearingTypePreference": {
              "type": "string",
              "enum": [
                "virtual_hearing",
                "video_conference",
                "central_office"
              ]
            },
            "requestingExtension": {
              "type": "boolean",
              "description": "Set to true to request a filing extension. An extensionReason must be provided if true."
            },
            "extensionReason": {
              "type": "string",
              "minLength": 1,
              "maxLength": 2300,
              "description": "Explanation why you believe there is good cause for the extension. If an extensionReason is provided, requestingExtension must be true."
            },
            "appealingVhaDenial": {
              "type": "boolean",
              "description": "Set to true if you are appealing a denial of benefits by the Veterans Health Administration (VHA)."
            }
          },
          "required": [
            "boardReviewOption"
          ],
          "if": {
            "properties": {
              "requestingExtension": {
                "const": true
              }
            }
          },
          "then": {
            "required": [
              "extensionReason"
            ]
          }
        }
      },
      "required": [
        "type",
        "attributes"
      ]
    },
    "included": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "type": {
            "type": "string",
            "enum": [
              "appealableIssue"
            ]
          },
          "attributes": {
            "type": "object",
            "properties": {
              "issue": {
                "type": "string",
                "minLength": 1,
                "maxLength": 180
              },
              "decisionDate": {
                "type": "string",
                "format": "date"
              },
              "decisionIssueId": {
                "type": "integer"
              },
              "ratingIssueReferenceId": {
                "type": "string",
                "minLength": 1,
                "maxLength": 255
              },
              "ratingDecisionReferenceId": {
                "type": "string",
                "minLength": 1,
                "maxLength": 255
              },
              "disagreementArea": {
                "type": "string",
                "maxLength": 90
              }
            },
            "required": [
              "issue",
              "decisionDate"
            ]
          }
        },
        "required": [
          "type",
          "attributes"
        ]
      },
      "minItems": 1,
      "maxItems": 100,
      "uniqueItems": true
    }
  },
  "required": [
    "data",
    "included"
  ]
}

